-- Source-anchored educational starter collection. No inferred clinical efficacy or seller endorsements.
-- References verified from Quran 16:69, 23:20 and Sahih al-Bukhari 5688, 5689, 5445, 887, 5696, 5736.
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('honey','honey','Honey','العسل','Honey from bees','food','honey,asal,bees,cough,food','Quran 16:69 speaks of a drink produced by bees with healing for people.','Quran 16:69','https://quran.com/16/69','The Quranic passage describes a sign in creation and a healing association; it does not establish efficacy for every disease.','Do not give honey to infants under 12 months. Food allergy and medical circumstances may require professional advice.','Ingredient availability may be explored independently of any therapeutic claim.','yes','pending','published','1');
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('black-seed','black-seed','Black Seed','الحبة السوداء','Nigella sativa','food','kalonji,black cumin,black seed,nigella,oil','The Prophet ﷺ spoke about black seed in an authenticated narration.','Sahih al-Bukhari 5688','https://sunnah.com/bukhari:5688','The wording of the narration should not be turned into a claim of clinically proven universal treatment. Research must be assessed for each condition and preparation.','Concentrated oils and extracts are not interchangeable with food seeds. Discuss supplements with a qualified clinician, especially during pregnancy, chronic illness or medication use.','Food-grade seed or oil availability may be listed separately after seller verification.','yes','pending','published','2');
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('talbina','talbina','Talbina','التلبينة','Barley-based porridge','food','talbina,barley,porridge,grief,food','Aisha (RA) recommended talbina when people were ill or grieving.','Sahih al-Bukhari 5689','https://sunnah.com/bukhari:5689','The narration relates to comfort; it must not be presented as clinical treatment for depression or other mental-health conditions.','Barley contains gluten; unsuitable for people with coeliac disease or barley allergy. Seek help for persistent or severe emotional distress.','Ingredient sellers may offer barley or prepared talbina without implying medical efficacy.','yes','pending','published','3');
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('ajwa-dates','ajwa-dates','Ajwa Dates','العجوة','Phoenix dactylifera — Ajwa cultivar','food','ajwa,dates,madinah,date palm,food','Ajwa dates are mentioned in an authenticated narration with specific religious wording.','Sahih al-Bukhari 5445','https://sunnah.com/bukhari:5445','Preserve the text and religious interpretation of the narration. It does not justify withholding emergency treatment for poisoning or claiming that retail dates prevent poison.','Dates contain natural sugars. Individual nutritional needs, including diabetes management, vary; poisoning requires urgent medical attention.','Verified Ajwa varietal identity and provenance matter before any seller listing.','yes','pending','published','4');
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('olive','olive','Olive & Olive Oil','الزيتون','Olea europaea','food','olive,olive oil,fruit,food','The Quran describes the olive-bearing tree and its oil among foods.','Quran 23:20','https://quran.com/23/20','The verse identifies food and oil; it should not be recast as an evidence-based cure for a medical condition.','Food-grade olive oil is different from concentrated plant extracts. Claims about product grade or origin need independent verification.','Availability can cover accurately labelled food-grade oils.','yes','pending','published','5');
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('miswak','miswak','Miswak / Siwak','السواك','Salvadora persica and other siwak materials','care','siwak,miswak,oral hygiene,teeth,cleaning','The Prophetic tradition encourages use of the siwak with prayer.','Sahih al-Bukhari 887','https://sunnah.com/bukhari:887','Religious encouragement for oral cleanliness does not replace regular dental assessment or evidence-based dental care.','Use clean, hygienically stored oral-care material; avoid injuring gums. Continue appropriate brushing, fluoride and dental guidance.','Only products accurately identifying material and seller can qualify for availability listings.','yes','pending','published','6');
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('hijama','hijama','Hijama / Cupping','الحجامة','Cupping procedure','practice','hijama,cupping,bloodletting,procedure','Cupping appears in authenticated narrations concerning care and practice.','Sahih al-Bukhari 5696','https://sunnah.com/bukhari:5696','A recorded historic procedure is not proof of effectiveness or suitability for a particular modern condition.','Wet cupping carries bleeding, infection and other risks; do not attempt it from a website. Clinical evaluation and properly licensed care are essential.','No self-treatment products or practitioner endorsements are offered.','no','pending','published','7');
INSERT OR IGNORE INTO tibb_entries (id,slug,title,arabic_name,scientific_name,category,tags,tradition_summary,reference_label,reference_url,health_context,safety_note,availability_note,seller_eligible,review_stage,status,sort_order) VALUES ('ruqyah','ruqyah','Ruqyah','الرقية','Quranic recitation and supplication','spiritual','ruqyah,fatiha,dua,recitation,spiritual','Authenticated traditions describe recitation of Al-Fatiha in a ruqyah context.','Sahih al-Bukhari 5736','https://sunnah.com/bukhari:5736','Spiritual practice belongs in its religious context; narratives must not be advertised as a substitute for emergency or necessary medical care.','Never delay urgent treatment, including after a snakebite, poisoning or serious illness. Be cautious of exploitative paid cure claims.','Not a purchasable ingredient; no seller offers on this topic.','no','pending','published','8');
